import axios from 'axios';

export const API_URL = 'http://localhost:5000/api';

export const testConnection = async () => {
  try {
    await axios.get(`${API_URL}/health`);
    return { success: true };
  } catch {
    return { success: false };
  }
};

export default axios.create({
  baseURL: API_URL,
});
